"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Second backbone: dev evaluation with the first backbone's frozen report code, the run folder redirected to the
second backbone's outputs (docs/evaluation_protocol.md, section 17: every script and criterion
of the first backbone; only the backbone is swapped).

bind(root) points every module of the L1 family at a run folder (data/p1v4/runs for the first backbone,
data/p1v4/runs_bb2 for the second). The rivals that do not depend on the backbone (API systems, T, L2, L3, B1-strong)
keep their stored dev outputs: their files are copied into the second backbone's grounding folder unchanged.
Commands:
  settings [bb1]   thresholds of every L1-family read-out on natural dev by the plan's operating-point rule (as the
                   rehearsal record, p1v4_freeze.settings) -> results/main_v04_bb2/settings_dev.json; with "bb1" the
                   same code on the first backbone's files, compared with its rehearsal record (a check of this code)
  copy             the backbone-independent dev inputs of the grounding report into data/p1v4/runs_bb2/grounding/dev
  grounding        p1v4_grounding_v06.main on dev (matched-condition criteria; with_natural=False: the natural part
                   reads the final run's files, which the second backbone gets only at its own test-day run)
                   -> results/main_v04_bb2/grounding_v06_dev.json
  readout2d        p1v4_readout_2d.eval_ -> results/main_v04_bb2/readout_2d_dev.json
  offsets [bb1]    the decision-offset check (G4b) on the stored offset features -> results/main_v04_bb2/offsets_2d_dev.json;
                   "bb1": the first backbone on the same items (laptop GPU), compared with its stored result
  mirror           evidence-reliability step 1 on dev (as p1v4_reliability_dev.report: accuracy, confidence and
                   confident errors per level and condition for 2d and the old head)
                   -> results/main_v04_bb2/reliability_step1_dev.json
Every command except copy prints which files it read under the first backbone's run folder (Audit).
usage (repo root): .venv-gpu/Scripts/python.exe -X utf8 scripts/bb2_report.py <command> [bb1]
"""
import collections
import copy
import json
import os
import re
import shutil
import sys

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

BB1, BB2 = "data/p1v4/runs", "data/p1v4/runs_bb2"
RES1, RES2 = "results/main_v04", "results/main_v04_bb2"


def bind(root):
    """Redirect the L1 family's run folders to root (module constants read at call time)."""
    import p1v4_conditional as CV
    import p1v4_control_starts as CS
    import p1v4_ears_time_diag as ET
    import p1v4_grounding as G
    import p1v4_grounding_v06 as V6
    import p1v4_readout as RO
    import p1v4_readout_2c as R2C
    import p1v4_readout_2d as R2D
    import p1v4_readout_allclass as AC
    import p1v4_readout_extra as RX
    import p1v4_reliability_dev as RD
    G.R = V6.R = RO.R = R2C.R = R2D.R = AC.R = RX.R = RD.R = root
    RO.OUT = CV.OUT = f"{root}/readout"
    AC.OUT = f"{root}/grounding/allclass"
    R2C.OUT = f"{root}/grounding/allclass2c"
    R2D.OUT = f"{root}/grounding/allclass2d"
    RX.OUT = f"{root}/grounding/extra"
    CS.CDIR = f"{root}/grounding/control"
    RD.OUT = f"{root}/reliability/dev"
    ET.OUT = R2D.DEV_SEC = f"{root}/ears_time/feats_dev.npz"
    R2D.Sec.__init__.__defaults__ = (R2D.DEV_SEC, None, None, None)
    if root != BB1:
        R2D.RES = RES2
        RX.RES = f"{RES2}/readout_extra_dev.json"


def natural_dev(root):
    """The natural dev features of the L1 family with the per-second ears joined by window id."""
    import p1v4_readout as RO
    z = dict(np.load(f"{RO.OUT}/feats_dev_natural.npz"))
    if "sec_mean" not in z:
        e = np.load(f"{root}/ears_time/feats_dev.npz")
        pos = {i: n for n, i in enumerate(e["ids"])}
        r = [pos[i] for i in z["ids"]]
        z["sec_mean"], z["sec_max"] = e["sec_mean"][r], e["sec_max"][r]
    return z


def settings(which="bb2"):
    import p1v4_combo_pilot as CP
    import p1v4_control_starts as CS
    import p1v4_data as D
    import p1v4_freeze as FZ
    import p1v4_readout as RO
    import p1v4_readout_2c as R2C
    import p1v4_readout_2d as R2D
    import p1v4_readout_allclass as AC
    import p1v4_readout_extra as RX
    import p1v4_score as S
    root = BB1 if which == "bb1" else BB2
    bind(root)
    rows = D.load_rows("dev")
    zn = natural_dev(root)
    keyed = lambda d: {(k.split("|")[0], k.split("|")[1], int(k.split("|")[2])): v for k, v in d.items()}  # noqa: E731

    def op(sc):
        o = S.operating_point(rows, sc)
        return {"th_s": float(o["th_s"]), "th_r": float(o["th_r"]), "primary": float(o["primary"]),
                "floors_met": bool(o["floors_met"]), "lowest_floor": float(o["lowest_floor"])}
    old = keyed(json.load(open(f"{root}/l1/scores_dev.json")))
    ro = {"s2": RO.load_readouts(), "2b": AC.load_allclass(), "2c": R2C.load_2c()}
    got = {"old head": op(old),
           "step 2 states": op(RO.scores_of(zn, "states", ro["s2"])), "step 2 ears": op(RO.scores_of(zn, "ears", ro["s2"])),
           "2b states": op(RO.scores_of(zn, "states", ro["2b"])), "2b ears": op(RO.scores_of(zn, "ears", ro["2b"])),
           "2c states": op(RO.scores_of(zn, "states", ro["2c"])), "2c ears": op(RO.scores_of(zn, "ears", ro["2c"])),
           "2d": op(R2D.scores_2d(zn, R2D.Sec(None, zn["ids"], zn["sec_mean"], zn["sec_max"]), R2D.load_2d()))}
    l3 = keyed(json.load(open(f"{BB1}/l3/scores_dev.json")))                # L3 does not depend on the backbone
    got["combination"] = op(CP.combine(old, l3, "logit", 0.5)[0])
    got["control starts"] = {str(s): op(RO.scores_of(zn, "states", CS.load_start(s))) for s in CS.STARTS}
    got["extra"] = {n: op(RX.scores(n, zn, RX.load(n))) for n in RX.NAMES}
    reh = json.load(open(FZ.REHEARSAL))["settings"]
    if which == "bb1":                                  # the code check: reproduce the rehearsal record
        ref = {"old head": reh["local"]["L1"], **{n: reh["readouts"][n] for n in (
            "step 2 states", "step 2 ears", "2b states", "2b ears", "2c states", "2c ears", "2d", "combination")}}
        worst = {}
        for n, r in ref.items():
            worst[n] = max(abs(got[n]["th_s"] - r["th_s"]), abs(got[n]["th_r"] - r["th_r"]))
        for s, r in reh["readouts"]["control starts"].items():
            worst[f"control start {s}"] = max(abs(got["control starts"][s]["th_s"] - r["th_s"]),
                                              abs(got["control starts"][s]["th_r"] - r["th_r"]))
        for n, r in reh["readouts"]["extra"].items():
            worst[f"extra {n}"] = max(abs(got["extra"][n]["th_s"] - r["th_s"]), abs(got["extra"][n]["th_r"] - r["th_r"]))
        bad = {k: v for k, v in worst.items() if v > 1e-9}
        print(json.dumps({"read-outs compared": len(worst), "different": bad}, indent=1))
        return
    st = copy.deepcopy(reh)                              # rivals' entries stay the first run's (backbone-independent)
    st["local"]["L1"] = {"th_s": got["old head"]["th_s"], "th_r": got["old head"]["th_r"]}
    for n in ("step 2 states", "step 2 ears", "2b states", "2b ears", "2c states", "2c ears", "2d", "combination"):
        st["readouts"][n].update(th_s=got[n]["th_s"], th_r=got[n]["th_r"])
        if "file" in st["readouts"][n]:
            st["readouts"][n]["file"] = st["readouts"][n]["file"].replace(BB1, BB2)
    for s, v in st["readouts"]["control starts"].items():
        v.update(th_s=got["control starts"][s]["th_s"], th_r=got["control starts"][s]["th_r"],
                 path=v["path"].replace(BB1, BB2))
    for n, v in st["readouts"]["extra"].items():
        v.update(th_s=got["extra"][n]["th_s"], th_r=got["extra"][n]["th_r"], file=v["file"].replace(BB1, BB2))
    st["main"].update(th_s=got["2d"]["th_s"], th_r=got["2d"]["th_r"], file=st["main"]["file"].replace(BB1, BB2))
    os.makedirs(RES2, exist_ok=True)
    json.dump({"backbone": "Voxtral Mini 3B (second backbone)", "natural_dev": got, "settings": st},
              open(f"{RES2}/settings_dev.json", "w"), indent=1)
    for n, v in got.items():
        if n not in ("control starts", "extra"):
            print(f"{n:14s} th S {v['th_s']:.4g} R {v['th_r']:.4g}  five-part {v['primary']:.4f}  floors met "
                  f"{v['floors_met']} (lowest {v['lowest_floor']:.3f})", flush=True)


def offsets(which="bb2", split="dev"):
    """= the scoring part of p1v4_readout_2d.offsets on stored offset features (bb2_pipeline devoff; on test
    bb2_test.py testoff); for "bb1" (dev only) the first backbone's features are computed here from the same items
    (VoxTurn, batch 1) so that the result can be compared with its stored results/main_v04/offsets_2d_dev.json.
    split (2026-11-25, for the test run): the split's groups, features and output file; the settings stay those of
    settings_dev.json (frozen in results/main_v04_bb2/freeze_bb2.json)."""
    if which == "bb1" and split != "dev":
        raise SystemExit("the backbone-1 code check is on dev only")
    import p1v4_freeze as FZ
    import p1v4_grounding as G
    import p1v4_grounding_report as GR
    import p1v4_readout as RO
    import p1v4_readout_2c as R2C
    import p1v4_readout_2d as R2D
    import p1v4_readout_allclass as AC
    import p1v4_score as S
    root = BB1 if which == "bb1" else BB2
    bind(root)
    st = json.load(open(FZ.REHEARSAL))["settings"] if which == "bb1" else load_settings()
    rows, rows_by = G.load(split)
    groups = [g for g in G.load_groups(split) if g["part"] == "s_move" and rows_by[(g["unit"], "1")]["subset"] is None]
    feats = {}
    for d in R2D.OFFSETS:
        p = f"{root}/offsets/{split}/l1_d{d:+.1f}.npz" if which == "bb2" else f"{BB2}/offsets/dev_bb1/l1_d{d:+.1f}.npz"
        if which == "bb1" and not os.path.exists(p):
            import soundfile as sf
            import torch
            import p1v4_l1 as L1
            from p1v4_readout_2d import per_second
            model = L1.build()
            L1.load_new_state(model, torch.load(f"{BB1}/l1/l1_new.pt", weights_only=True))
            model.eval()
            its = json.load(open(f"{BB2}/items/devoff_d{d:+.1f}.json"))
            H, E, SM, SX, QW, QT, PO = [], [], [], [], [], [], []
            for i, it in enumerate(its):
                wave = torch.from_numpy(sf.read(it["path"], dtype="float32")[0])[None].cuda()
                h, e, qw, po = RO.forward_states(model, wave, [it["text"]], [it["marker"]],
                                                 [[RO.TASK[q] for q in it["qs"]]])
                sm, sx, _ = per_second(model.vt, wave)
                H.append(h)
                E.append(e)
                SM.append(sm)
                SX.append(sx)
                QW.append(qw + i)
                QT += it["qs"]
                PO.append(po)
            os.makedirs(os.path.dirname(p), exist_ok=True)
            np.savez(p, states=np.concatenate(H), ears=np.concatenate(E), sec_mean=np.concatenate(SM),
                     sec_max=np.concatenate(SX), q_win=np.concatenate(QW), q_task=np.array(QT),
                     p_old=np.concatenate(PO), ids=np.array([it["id"] for it in its]))
            del model
            torch.cuda.empty_cache()
        feats[d] = dict(np.load(p))
    th_old = (st["local"]["L1"]["th_s"], st["local"]["L1"]["th_r"])
    n2b = (st["readouts"]["2b ears"]["th_s"], st["readouts"]["2b ears"]["th_r"])
    n2c = (st["readouts"]["2c ears"]["th_s"], st["readouts"]["2c ears"]["th_r"])
    n2d = (st["main"]["th_s"], st["main"]["th_r"])
    ro_2b, ro_2c, ro_2d = AC.load_allclass(), R2C.load_2c(), R2D.load_2d()
    cl = GR.cluster_table(rows, split)
    units = [g["unit"] for g in groups]
    res, right = {"n_groups": len(groups), "offsets_after_door_onset_s": [1.0 + d for d in R2D.OFFSETS],
                  "by_offset": {}}, {}
    for d in R2D.OFFSETS:
        z = feats[d]
        sec = R2D.Sec(None, z["ids"], z["sec_mean"], z["sec_max"])
        systems = {"2d": (R2D.scores_2d(z, sec, ro_2d), n2d), "2c ears": (RO.scores_of(z, "ears", ro_2c), n2c),
                   "2b ears": (RO.scores_of(z, "ears", ro_2b), n2b), "old head": (RO.scores_of(z, None, None), th_old)}
        res["by_offset"][f"{1.0 + d:.1f} s"] = {}
        for name, (sc, th) in systems.items():
            ev = GR.group_eval(groups, rows_by, S.decide(sc, *th), sc)
            right[(name, d)] = np.array([ev[u]["right"] for u in units])
            res["by_offset"][f"{1.0 + d:.1f} s"][name] = {
                "group_all_right": float(right[(name, d)].mean()),
                "hit_v1": float(np.mean([ev[u]["follow_event"] for u in units])),
                "false_alarms_v2_4": float(np.mean([ev[u]["follow_none"] for u in units])),
                "concordance": float(np.mean([ev[u]["conc"] for u in units]))}
    shifted = [d for d in R2D.OFFSETS if d != 0.0]
    a = np.mean([right[("2d", d)] for d in shifted], 0)
    b = np.mean([right[("2c ears", d)] for d in shifted], 0)
    c = GR.criterion(units, cl, {}, lambda w: GR.wmean(w, a) - GR.wmean(w, b), lambda: float(a.mean() - b.mean()))
    g4m = st["grounding"]["g4_margin"]
    res["rule 4: shifted offsets, 2d - 2c ears group all-right >= +0.10"] = {
        "point": c["point"], "ci95": c["ci95"], "ci95_normal": c["ci95_normal"], "df": c["df"],
        "dominant_factor": c["dominant_factor"], "n_clusters": c["n_clusters"], "margin": g4m,
        "pass": bool(c["point"] >= g4m and c["ci95"][0] > 0),
        "note": "all main-body S-move groups; the grounding report (v0.6) recomputes it without identity-dropped groups"}
    # = p1v4_readout_2d.offsets: per-unit rights, which the grounding report's G4b criterion row reads (2026-11-25 fix)
    res["per_unit_right"] = {name: {f"{d:+.1f}": dict(zip(units, map(float, right[(name, d)]))) for d in R2D.OFFSETS}
                             for name in ("2d", "2c ears", "2b ears", "old head")}
    if which == "bb1":                                  # the code check against the stored first-backbone result
        ref = json.load(open("results/main_v04/offsets_2d_dev.json"))
        worst = max(abs(res["by_offset"][o][n][f] - ref["by_offset"][o][n][f]) for o in res["by_offset"]
                    for n in res["by_offset"][o] for f in res["by_offset"][o][n])
        pu = max(abs(res["per_unit_right"][n][d][u] - ref["per_unit_right"][n][d][u]) for n in res["per_unit_right"]
                 for d in res["per_unit_right"][n] for u in res["per_unit_right"][n][d])
        same_units = all(set(res["per_unit_right"][n][d]) == set(ref["per_unit_right"][n][d])
                         for n in res["per_unit_right"] for d in res["per_unit_right"][n])
        print(f"offsets code check against results/main_v04/offsets_2d_dev.json: max difference {worst:.2e}; "
              f"per-unit rights max difference {pu:.2e}, same units {same_units}", flush=True)
        return
    os.makedirs(RES2, exist_ok=True)
    json.dump(res, open(f"{RES2}/offsets_2d_{split}.json", "w"), indent=1)
    for off, row in res["by_offset"].items():
        print(f"after door onset {off}: " + " | ".join(f"{n} {x['group_all_right']:.3f}" for n, x in row.items()),
              flush=True)
    print("rule 4:", json.dumps(res["rule 4: shifted offsets, 2d - 2c ears group all-right >= +0.10"]), flush=True)


class Audit:
    """Records every file the evaluation opens under the first backbone's run folder, so that a second-backbone report
    can be checked to read only backbone-independent inputs from there.
    deny=True (the test run, 2026-11-25 review M1): print every such file in full and stop if any of them is one that
    depends on the backbone (the L1 family's outputs, read-outs, offsets, noise runs and reports)."""
    DENY_RUN = re.compile(r"^data/p1v4/runs/(final/[^/]+/(l1|readouts|offsets|noise)/|grounding/[^/]+/l1_|readout/|"
                          r"grounding/(allclass|allclass2c|allclass2d|control|extra)/|l1/|ears_time/|reliability/)")
    DENY_RES = re.compile(r"^results/main_v04/(offsets_2d_|noise_|readout_|grounding_v06_|decision_)")

    def __init__(self, deny=False):
        self.deny = deny

    def __enter__(self):
        import builtins
        self.paths, self._open, self._load = [], builtins.open, np.load

        def opn(f, *a, **k):
            self.paths.append(str(f))
            return self._open(f, *a, **k)

        def load(f, *a, **k):
            self.paths.append(str(f))
            return self._load(f, *a, **k)
        builtins.open, np.load = opn, load
        return self

    def __exit__(self, *exc):
        import builtins
        builtins.open, np.load = self._open, self._load
        bb1 = sorted({p.replace("\\", "/") for p in self.paths if p.replace("\\", "/").startswith(BB1 + "/")})
        groups = collections.Counter("/".join(p.split("/")[:5]) for p in bb1)
        print("files read under the first backbone's run folder:", json.dumps(dict(groups), indent=1), flush=True)
        res1 = sorted({p.replace("\\", "/") for p in self.paths if p.replace("\\", "/").startswith(RES1 + "/")})
        print("files read under the first backbone's results folder:", json.dumps(res1, indent=1), flush=True)
        self.bb1, self.res1 = bb1, res1
        if self.deny:
            print("first-backbone files read, in full:", json.dumps(bb1 + res1, indent=1), flush=True)
            bad = [p for p in bb1 if self.DENY_RUN.match(p)] + [p for p in res1 if self.DENY_RES.match(p)]
            if bad and exc[0] is None:
                raise SystemExit(f"backbone-dependent first-backbone files were read: {bad}")
        return False


def load_settings():
    return json.load(open(f"{RES2}/settings_dev.json"))["settings"]


def copy_inputs():
    """The backbone-independent inputs of the grounding report: the API answers, the local rivals' scores, groups."""
    src, dst = f"{BB1}/grounding/dev", f"{BB2}/grounding/dev"
    os.makedirs(dst, exist_ok=True)
    n = 0
    for name in os.listdir(src):
        if name == "api" or name.startswith("local_") or name == "groups.json":
            s, d = os.path.join(src, name), os.path.join(dst, name)
            if os.path.isdir(s):
                if os.path.exists(d):
                    shutil.rmtree(d)
                shutil.copytree(s, d)
            else:
                shutil.copy2(s, d)
            n += 1
    print(f"copied {n} entries from {src} to {dst}", flush=True)


def grounding():
    import p1v4_grounding_v06 as V6
    bind(BB2)
    st = load_settings()
    V6.settings = lambda split: st
    # 2026-11-25 fix: the report reads G4b from {RES}/offsets_2d_dev.json and G5 from {RES}/noise_dev.json; without this
    # line both came from the first backbone's results folder. G4b now reads `offsets` above (run it first); G5 (the
    # front-end degradation run, p1v4_noise_final) has no second-backbone run, so the dev report leaves it out.
    V6.RES = RES2
    if not os.path.exists(f"{RES2}/offsets_2d_dev.json") or "per_unit_right" not in json.load(
            open(f"{RES2}/offsets_2d_dev.json")):
        raise SystemExit("run `bb2_report.py offsets` first (the G4b row reads its per-unit rights)")
    os.makedirs(RES2, exist_ok=True)
    V6.main("dev", out=f"{RES2}/grounding_v06_dev.json", with_natural=False)


def readout2d():
    import p1v4_readout_2d as R2D
    bind(BB2)
    R2D.eval_()


def mirror():
    """= p1v4_reliability_dev.report for 2d and the old head (the two systems of the mirror), second backbone."""
    import p1v4_readout as RO
    import p1v4_readout_2d as R2D
    import p1v4_conditional as CV
    import p1v4_reliability_dev as RD
    import p1v4_step0_confidence as S0
    bind(BB2)
    st = load_settings()
    th = {"2d": (st["main"]["th_s"], st["main"]["th_r"]), "old head": (st["local"]["L1"]["th_s"],
                                                                         st["local"]["L1"]["th_r"])}
    ro2d, probe = R2D.load_2d(), dict(np.load(f"{BB2}/readout/ears_probe.npz"))
    res = {"split": "dev", "backbone": "Voxtral Mini 3B", "thresholds": th, "cells": {}, "groups_all_right": {},
           "ears_probe": {}}
    for lv in RD.LEVELS:
        for cond in RD.CONDS:
            z = dict(np.load(f"{RD.OUT}/{lv}/l1_{cond}.npz"))
            sc = {"2d": R2D.scores_2d(z, R2D.Sec(None, z["ids"], z["sec_mean"], z["sec_max"]), ro2d),
                  "old head": RO.scores_of(z, None, None)}
            if cond == "none":
                rh = np.array([str(p) == "r_hear" for p in z["parts"]])
                pe = CV.probe_p(z["ears"], probe)
                res["ears_probe"][lv] = float(np.mean((pe[rh] >= CV.EARS_CUT) == z["real"][rh].astype(bool)))
            for n in ("2d", "old head"):
                qs = RD.questions(z, RD.keyed(sc[n]), th[n])
                for part in ("r_hear", "s_move"):
                    sel = [x for x in qs if x[1] == part]
                    if not sel:
                        continue
                    res["cells"].setdefault(part, {}).setdefault(cond, {}).setdefault(n, {})[lv] = \
                        S0.summary([x[4] for x in sel], [x[5] for x in sel])
                    ok = collections.defaultdict(lambda: True)
                    for x in sel:
                        ok[x[0]] = ok[x[0]] and bool(x[5])
                    res["groups_all_right"].setdefault(part, {}).setdefault(cond, {}).setdefault(n, {})[lv] = \
                        float(np.mean(list(ok.values())))
    os.makedirs(RES2, exist_ok=True)
    json.dump(res, open(f"{RES2}/reliability_step1_dev.json", "w"), indent=1)
    for part in ("r_hear", "s_move"):
        for cond in ("none", "truth"):
            for n in ("2d", "old head"):
                c = res["cells"][part][cond][n]
                print(f"{part} {cond:5s} {n:8s} " + "  ".join(f"{lv[1:]:8s} acc {c[lv]['accuracy']:.3f}"
                                                             for lv in RD.LEVELS), flush=True)


if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "settings":
        with Audit():
            settings("bb1" if len(a) > 1 and a[1] == "bb1" else "bb2")
    elif a == ["copy"]:
        copy_inputs()
    elif a and a[0] == "offsets":
        with Audit():
            offsets("bb1" if len(a) > 1 and a[1] == "bb1" else "bb2")
    elif a and a[0] in ("grounding", "readout2d", "mirror"):
        with Audit():
            {"grounding": grounding, "readout2d": readout2d, "mirror": mirror}[a[0]]()
    else:
        raise SystemExit(__doc__)
